    funds: 115
    sponsorIncome: 7.4
    operatingCost: 2.6
    targetPosition: 2
    facilities: { windTunnel: 4, cfd: 5, simulator: 5, factory: 5 }
    staff:
      technicalDirector: { name: 皮埃尔·瓦谢, skill: 87, salary: 3 }
      aeroChief: { skill: 84, salary: 2 }
      raceEngineer: { name: 詹皮耶罗·兰比亚塞, skill: 88, salary: 1.3 }
      pitCrew: { skill: 90, salary: 1.7 }
      strategist: { name: 汉娜·施密茨, skill: 87, salary: 1.2 }
    carBase: { perf: 76, rel: 83 }
    parts:
      power_unit: { perf: 87, rel: 78 }
      ers: { perf: 88, rel: 78 }
      gearbox: { perf: 75.9, rel: 82 }
      chassis: { perf: 75.9, rel: 85 }
      front_wing: { perf: 75.9, rel: 86 }
      rear_wing: { perf: 75.9, rel: 86 }
      floor: { perf: 76.9, rel: 85 }
      sidepods: { perf: 74.9, rel: 86 }
      suspension: { perf: 74.9, rel: 85 }
    description: RB22 · 红牛-福特动力单元（车队首台自研动力）。2025 年车队榜第 3（451 分）。季前动力单元表现令人意外，但测试初期出现液压问题。

