    short: FER
    color: '#dc0000'
    special: ferrari
    principal: 空缺（过渡领队）
    engine: 法拉利
    worksTeam: true
    base: 意大利·马拉内罗
    funds: 120
    sponsorIncome: 7.5
    operatingCost: 2.6
    targetPosition: 4
    facilities: { windTunnel: 4, cfd: 4, simulator: 5, factory: 5 }
    staff:
