    targetPosition: 5
    facilities: { windTunnel: 3, cfd: 4, simulator: 4, factory: 4 }
    staff:
      technicalDirector: { name: 帕特·弗莱, skill: 82, salary: 2.2 }
      aeroChief: { skill: 77, salary: 1.5 }
      raceEngineer: { skill: 78, salary: 0.9 }
      pitCrew: { skill: 82, salary: 1.2 }
      strategist: { skill: 78, salary: 0.9 }
    carBase: { perf: 49, rel: 82 }
    parts:
      power_unit: { perf: 91, rel: 87 }
      ers: { perf: 86, rel: 85 }
      gearbox: { perf: 50.9, rel: 84 }
